import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"否","description":"焦氏易林注 - 否","frontmatter":{"title":"否","description":"焦氏易林注 - 否"},"headers":[],"relativePath":"zh/classics/jiaoyilin/012.md","filePath":"zh/classics/jiaoyilin/012.md"}'),l={name:"zh/classics/jiaoyilin/012.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><h3 id="否-1" tabindex="-1">否 <a class="header-anchor" href="#否-1" aria-label="Permalink to “否”">​</a></h3><h3 id="否之乾" tabindex="-1">否之乾 <a class="header-anchor" href="#否之乾" aria-label="Permalink to “否之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>江河淮濟，天之奧府。眾利所聚，可以饒有，樂我君子。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《否》象。坤為江河淮濟。乾為天，坤為府、為眾，巽為利，坤為聚，故曰饒。艮為君子。○首句依汲古，宋元本無，非。濟、聚為韻。</p><h3 id="否之坤" tabindex="-1">否之坤 <a class="header-anchor" href="#否之坤" aria-label="Permalink to “否之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>天之所災，凶不可居。轉徙獲福，留止憂危。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>否坤為災、為凶，伏震為轉徙。震為福，故曰獲福。艮為留止，坤為憂危，言弗化也。坤為憂證，可釋《易》○憂危，依汲古，宋元作危憂。</p><h3 id="否之屯" tabindex="-1">否之屯 <a class="header-anchor" href="#否之屯" aria-label="Permalink to “否之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>名成德就，項領不試。景公耄老，尼父逝去。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為名、為成、為項領，坎伏，故不試。震為諸侯，艮為光，故曰景公。坤為老，艮為山，故曰尼父。震亦為父也。坤亡故曰逝去。《論語》：&quot;景公曰：吾老矣，不能用也&quot;，孔子行。○艮為名證。《毛詩》&quot;四牧項領&quot;註：項，大也。按：《魏書蘇則傳》註：則尋出兵，臨其項領，似不以大詁項字，林詞亦然。又按：《後漢呂強傳》：&quot;姦邪項領，膏唇拭舌&quot;，又杜詩：&quot;鄉裡兒童項領成&quot;，似皆以項領為壯盛強橫之兒，與詩詞合，異毛傳。</p><h3 id="否之蒙" tabindex="-1">否之蒙 <a class="header-anchor" href="#否之蒙" aria-label="Permalink to “否之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>持善避惡，福祿常存。雖有豹虎，不能危患。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮手為持，伏乾為善，坤為惡，坎隱，故曰避。震為福祿，艮為豹虎，坎為危患，震出險故無患。</p><h3 id="否之需" tabindex="-1">否之需 <a class="header-anchor" href="#否之需" aria-label="Permalink to “否之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>避患東西，反入禍門。糟糠不足，憂動我心。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《未濟》。○足，依汲古，宋元本作屬。</p><h3 id="否之訟" tabindex="-1">否之訟 <a class="header-anchor" href="#否之訟" aria-label="Permalink to “否之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>圭璧琮璋，執贄見王。百裡寧戚，應聘齊秦。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《井》，惟此以乾為圭璧琮璋。○王，宋本訛五。戚，宋元本作越。</p><h3 id="否之師" tabindex="-1">否之師 <a class="header-anchor" href="#否之師" aria-label="Permalink to “否之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>揚水潛鑿，使石潔白。里素表朱，游戲皋沃。得君所願，心志娛樂。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎為水，震為揚。坎為潛伏，巽為石、為白、為素，伏乾為表、為朱。震為戲游、為陵、為皋，坎為沃，震為君、為樂，坎為心志。《詩唐風》：&quot;揚之水，白石鑿鑿；素衣朱襮，從子於沃&quot;，註：鑿鑿，潔白貌。襮，領也。然則所謂潛鑿亦取伏巽象也。又襮即表。《呂氏春秋忠廉篇》：&quot;臣請為襮&quot;，高誘註曰：襮，表也。茲焦亦訓襮為表，與毛傳訓領異。又讀衣為里，尤異也。里，各本皆作衣，依《豫》之《大過》宋元本校。</p><h3 id="否之比" tabindex="-1">否之比 <a class="header-anchor" href="#否之比" aria-label="Permalink to “否之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>官爵相保，居之無咎。求兔不得，使伯悔恨。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為官爵、為居、為求。震為兔、為伯，震覆，故求兔不得。坎為憂，故曰悔恨。○使伯，依汲古，宋元作怕使，非。</p><h3 id="否之小畜" tabindex="-1">否之小畜 <a class="header-anchor" href="#否之小畜" aria-label="Permalink to “否之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>戴元無褌，裸裎出門。小兒作笑，君子憂患。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。艮為戴，坎為首，故曰戴元。元，首也。坤為褌，坤伏，故曰無褌。艮為皮膚、為身，故曰裸裎。艮為門，震出，故曰出門。震為子、為笑樂，艮小，故曰小兒作笑。艮為君子，坎為憂患。○戴元，宋本、汲古均作載車，依元本，全用對象。</p><h3 id="否之履" tabindex="-1">否之履 <a class="header-anchor" href="#否之履" aria-label="Permalink to “否之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>把珠入口，為我利寶。得吾所有，欣善嘉喜。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾為珠玉，兌口伏艮為手，故曰把珠入口。伏坤為我、為利、為吾。乾為嘉喜。○善，從汲古，宋元本皆作然。</p><h3 id="否之泰" tabindex="-1">否之泰 <a class="header-anchor" href="#否之泰" aria-label="Permalink to “否之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>行不如還，直不如屈。進不如退，可以安吉。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>內剛外柔方泰，乾進而外則否矣，故林詞以為戒。乾為行、為進，震為反，坤為安。○還、屈，從宋元本，汲古作止、作曲。</p><h3 id="否之否" tabindex="-1">否之否 <a class="header-anchor" href="#否之否" aria-label="Permalink to “否之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>秦為虎狼，與晉爭強。併吞其國，號曰始皇。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>此全用伏。兌為秦、為虎狼。震為晉、為爭，兌為吞。乾為皇、為始。</p><h3 id="否之同人" tabindex="-1">否之同人 <a class="header-anchor" href="#否之同人" aria-label="Permalink to “否之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>眾鬼瓦聚，中有大怪。九身無頭，魂驚魄去，不可以居。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤為鬼，坎亦為鬼，坎眾，故曰眾鬼。震為瓦，坤為聚，坎為怪。坤為身，震數九，故曰九身。坎為頭，坎伏，故曰無頭。震為神、為魂，坤為魄。震又為驚、為去也。○瓦聚，依汲古，宋元本作凡聚，瓦聚疑與瓦合瓦散同義。中有，宋元本作還生，依汲古。</p><h3 id="否之大有" tabindex="-1">否之大有 <a class="header-anchor" href="#否之大有" aria-label="Permalink to “否之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>家給人足，頌聲並作。四夷賓服，乾戈橐閣。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用否象。艮為家，伏震為人，坤聚，故曰給足。震為頌聲、為作，坤為夷，震卦數四，又為賓客，故曰四夷賓服。艮為乾戈，坤為囊，艮止，故曰橐閣。言偃武不用也。○橐，宋元本作囊，依汲古。</p><h3 id="否之謙" tabindex="-1">否之謙 <a class="header-anchor" href="#否之謙" aria-label="Permalink to “否之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>人面鬼口，長舌如斧。斫破瑚璉，殷商絕嗣。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為人，艮為面，坤為鬼，震為口，故曰人面鬼口。兌為舌，震形長於兌，故曰長舌。伏兌為斧，艮為斫，震為玉，故曰瑚璉。震為子，子為殷，商姓，坤為殺，震子被坤殺死，故殷商絕嗣也。○如斧，從汲古，宋元作為斧。</p><h3 id="否之豫" tabindex="-1">否之豫 <a class="header-anchor" href="#否之豫" aria-label="Permalink to “否之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>南山之峻，真人所在。德配唐虞，天命為子。保佑歆享，身受大慶。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為南，艮為山、為真人、為保佑。震為唐虞、為子、為慶，伏乾為天、為命。坤為身。</p><h3 id="否之隨" tabindex="-1">否之隨 <a class="header-anchor" href="#否之隨" aria-label="Permalink to “否之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>春桃生花，季女宜家。受福多年，男為邦君。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《坤》。</p><h3 id="否之蠱" tabindex="-1">否之蠱 <a class="header-anchor" href="#否之蠱" aria-label="Permalink to “否之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>鴟鴞破斧，沖人危殆。賴其忠德，轉禍為福，傾危復立。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為鴟鴞。兌為斧、為毀折，故曰破斧。艮為少子，故曰沖人。互大坎為忠德。震為福、為立，殆，音以。鴟鴞、破斧，豳風詩篇名。沖人，謂成王。忠德，指周公。</p><h3 id="否之臨" tabindex="-1">否之臨 <a class="header-anchor" href="#否之臨" aria-label="Permalink to “否之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>猿墮高木，不踒手足。保我金玉，還歸其室。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《艮》。</p><h3 id="否之觀" tabindex="-1">否之觀 <a class="header-anchor" href="#否之觀" aria-label="Permalink to “否之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>天之奧隅，堯舜所居。可以存身，保我邦家。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《復》。</p><h3 id="否之噬嗑" tabindex="-1">否之噬嗑 <a class="header-anchor" href="#否之噬嗑" aria-label="Permalink to “否之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>伯蹇叔盲，足病難行。終日至暮，不離其鄉。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為伯，坎為蹇，初四互大離，坎為叔，故曰叔盲。震足為行，坎病，故難行。離為日，艮為終，坎夜故曰終日至暮。艮為鄉，艮止，故不離。○病，依宋元，汲古作痛。</p><h3 id="否之賁" tabindex="-1">否之賁 <a class="header-anchor" href="#否之賁" aria-label="Permalink to “否之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>日月相望，光明盛昌。三聖茂功，仁德大隆。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《節》。○茂，從宋元本，汲古作成。</p><h3 id="否之剝" tabindex="-1">否之剝 <a class="header-anchor" href="#否之剝" aria-label="Permalink to “否之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>桃李花實，纍纍日息。長大成就，甘美可食。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《節》。○汲古多&quot;為我利福&quot;四字，宋本無，此用《否》象。巽為桃李，艮為實，伏兌為華。</p><h3 id="否之復" tabindex="-1">否之復 <a class="header-anchor" href="#否之復" aria-label="Permalink to “否之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>入和出明，動作有光。運轉休息，所為允康。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>入巽故曰和、出震故曰明。震為動作，震旦故曰光明，震出故運轉，龍潛在下故休息，出入無疾故允康。○動作，汲古作所為，依宋元本。</p><h3 id="否之無妄" tabindex="-1">否之無妄 <a class="header-anchor" href="#否之無妄" aria-label="Permalink to “否之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>陰衰老極，陽建其德。履離戴光，天下昭明。功業不長，蝦蟆大王。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《未濟》，此以巽為蝦蟆。○大，依汲古，宋元本作代。建，汲古作見，戴作載，俱依汲古《坤》之《未濟》校。</p><h3 id="否之大畜" tabindex="-1">否之大畜 <a class="header-anchor" href="#否之大畜" aria-label="Permalink to “否之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>行役未已，新事復起。姬薑勞苦，不得休止。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為行役、為起，伏坤為事，艮為光明，故曰新事。震為周，故曰姬。伏巽為齊，故曰薑。艮為休止，震起，故不得休止。</p><h3 id="否之頤" tabindex="-1">否之頤 <a class="header-anchor" href="#否之頤" aria-label="Permalink to “否之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>狐鳴室北，飢無所食。困於空邱，莫與同力。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為狐，震為鳴，艮為室，坤北，故曰室北。坤為飢，震為食，艮為困、為邱，坤虛，故曰空邱。○室，依汲古，宋元本作苑。○坤北證。</p><h3 id="否之大過" tabindex="-1">否之大過 <a class="header-anchor" href="#否之大過" aria-label="Permalink to “否之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>雄聖伏，名人匿。麟遠走，鳳飛北，擾亂未息。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為雄、為聖，伏艮為名，巽伏，故曰名人匿。坤文為麟，坤伏不見，故曰遠。坤為鳳、為北，坤伏故曰走、曰飛。按：韻前四句句皆三字，第五句乃為四字，漢魏叢書本竟以四字斷句，非。</p><h3 id="否之坎" tabindex="-1">否之坎 <a class="header-anchor" href="#否之坎" aria-label="Permalink to “否之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>疾貧望幸，使伯行販。開牢擇羊，多得大牂。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《遯》。</p><h3 id="否之離" tabindex="-1">否之離 <a class="header-anchor" href="#否之離" aria-label="Permalink to “否之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>翕翕，隕墜顛崩。滅其令名，長沒不存。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《謙》。○，依汲古，音橫，車聲，宋本作，音田，與下存韻。元本第二句作稍稍崩顛，與上韻，汲古則以崩為韻，且與下協。</p><h3 id="否之咸" tabindex="-1">否之咸 <a class="header-anchor" href="#否之咸" aria-label="Permalink to “否之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>華落實槁，衣敝如絡。女功不成，絲布如玉。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為華，巽為隕，故華落。艮為果實，艮火故槁。巽為絡、為敝，伏震為衣，巽落，故曰女功不成。巽為絲布，伏震為玉。○兌為華證可解《大過》九五。○華落實槁，依宋本，汲古作&quot;華薄實槁&quot;，非。功、如，從宋本，汲古作功、作為，非。</p><h3 id="否之恒" tabindex="-1">否之恒 <a class="header-anchor" href="#否之恒" aria-label="Permalink to “否之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>溫山松柏，常茂不落。鸞鳳所止，得其歡樂。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《坤》。○止，從宋元本，汲古作庇。其，從汲古，宋元作以。</p><h3 id="否之遯" tabindex="-1">否之遯 <a class="header-anchor" href="#否之遯" aria-label="Permalink to “否之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>失恃毋友，嘉偶出走。攫如失兔，傫如喪狗。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>坤伏風隕，故曰失恃。艮為友，巽寡，故毋友。坤為偶，震為嘉、為走，坤震皆伏，故曰嘉偶出走。艮手為攫，攫，撲也。震為兔、為失，失佚古通。佚兔，言兔逸也。艮為狗，巽寡，故曰傫如。伏坤為喪。○失恃毋友，依宋元本，汲古作&quot;失持母教&quot;，非。又攫如失兔、傫如喪狗，亦依宋元本，汲古作&quot;攫如失老，如喪家狗&quot;，尤非。</p><h3 id="否之大壯" tabindex="-1">否之大壯 <a class="header-anchor" href="#否之大壯" aria-label="Permalink to “否之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>太乙駕騮，從天上求。徵我叔季，封為魯侯。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤納乙，居北而互艮為星，故曰太乙。本卦震為駕、為騮、為從，乾為天，伏艮為求，故曰從天上求。艮為叔季，兌為魯，震為諸侯，故曰魯侯。○求，依宋元本，汲古等本皆作來，以文理言來順，以韻言求葉，未知孰是。又徵我叔季，亦依宋元本，汲古等本皆作微我季叔。</p><h3 id="否之晉" tabindex="-1">否之晉 <a class="header-anchor" href="#否之晉" aria-label="Permalink to “否之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>雙鳧俱飛，欲歸稻池，徑涉萑澤，為矢所射，傷我胸臆。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《旅》。以坎為矢，與易經合，舊說以離為矢，誤。</p><h3 id="否之明夷" tabindex="-1">否之明夷 <a class="header-anchor" href="#否之明夷" aria-label="Permalink to “否之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>深坑復平，天下安寧。意娛心樂，賴福長生。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎陷，故曰深坑。坎又為平，故曰復平。坤為天下，坤順，故曰安寧。震為娛樂，坎為心意，震為福、為長生。○坑，依宋本，他本皆作坎。</p><h3 id="否之家人" tabindex="-1">否之家人 <a class="header-anchor" href="#否之家人" aria-label="Permalink to “否之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>俱為天民，雲過吾西。風伯雨師，與我無恩。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《否》象。乾天坤民，故曰天民。坤為雲，伏兌為西，巽為風，伏震，故曰風伯。伏兌為雨，故曰雨師。《獨斷雲》：風伯箕星，雨師畢星，艮為星，故曰風伯、曰雨師。小畜雲：密雲不雨，自我西郊。與我無恩者，言上風下火，雨澤不至也○雨師，依宋元本，汲古等本皆訛為疾雨。</p><h3 id="否之睽" tabindex="-1">否之睽 <a class="header-anchor" href="#否之睽" aria-label="Permalink to “否之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>野鳥山鵲，來集六博。三梟四散，主人勝客。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鳥、為山野，坎為集，數六，故曰來集六博。梟、雉，皆博採名，故曰野鳥山鵲。兌上缺，故曰三梟。離卦數三，三梟四散，必當時六博採名，《戰國策》雲：夫梟棊之所以能為者，以散棊能佐之也。夫一梟不勝五散，明矣，茲曰三梟四散，孰勝負皆不能解。○梟，依汲古，宋元本作島。</p><h3 id="否之蹇" tabindex="-1">否之蹇 <a class="header-anchor" href="#否之蹇" aria-label="Permalink to “否之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>北陰司寒，堅冰不溫。凌人惰怠，大雹為災。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《噬嗑》。○惰怠，汲古、宋元作情，依局本。</p><h3 id="否之解" tabindex="-1">否之解 <a class="header-anchor" href="#否之解" aria-label="Permalink to “否之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>伊伯智士，去桀耕野。執順以待，反和無咎。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為音、為伯，故曰伊伯。伊吾，讀書聲也。坎為智，故曰智士。離為惡人，故曰桀。震為耕，否艮為野、為執、為待，坎為和。○伯，從汲古，宋元本作傅。《孟子》：伊尹耕於有莘之野而樂堯舜之道。</p><h3 id="否之損" tabindex="-1">否之損 <a class="header-anchor" href="#否之損" aria-label="Permalink to “否之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>秋風牽手，相從笑語。伯歌季舞，燕樂以喜。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，坤為風，艮手為牽，震為笑語，為從。二上正反震，故曰相從笑語。震為伯、為歌舞，艮為季，兌為燕。○秋，宋元本作北，依汲古。詩：北風其涼，攜手同行。從，依宋元本，汲古作提。</p><h3 id="否之益" tabindex="-1">否之益 <a class="header-anchor" href="#否之益" aria-label="Permalink to “否之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>徙巢去家，南過白馬。東西受福，與母相得。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為巢、為家，震為徙、為去、為南，巽為白，坤為馬，故曰白馬。白馬，津名，在大伾山南。震為東，伏兌為西。震為福，坤為母。○徙，依汲古，宋元本作從。</p><h3 id="否之夬" tabindex="-1">否之夬 <a class="header-anchor" href="#否之夬" aria-label="Permalink to “否之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛跌跛，兩兩相和。不病四支，但去莫疑。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鳥、為飛，兌折故跌跛。坤數二，重坤，故曰兩兩，兌為和，坤為病、為疑，坤伏，故不病不疑。</p><h3 id="否之姤" tabindex="-1">否之姤 <a class="header-anchor" href="#否之姤" aria-label="Permalink to “否之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>三牛生狗，以戌為母。荊夷上侵，姬伯出走。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《震》。○狗，宋元本作駒，非。</p><h3 id="否之萃" tabindex="-1">否之萃 <a class="header-anchor" href="#否之萃" aria-label="Permalink to “否之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>破筐敝筥，棄捐於道。壞落穿敗，不復為寶。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。震為筐筥。兌為破，巽為敝，艮為道，艮止不用，故曰棄捐，兌毀，故曰壞落穿敗。震為玉、為寶，震覆，故不為寶。○為，依宋元本，他本皆作所，非。</p><h3 id="否之升" tabindex="-1">否之升 <a class="header-anchor" href="#否之升" aria-label="Permalink to “否之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>結紐得解，憂不為禍。食利供家，受福安坐。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>巽為結紐。震為解、為樂，故憂不為禍。坤為憂、為禍也。巽為利，兌口，故曰食利。伏艮為家、為安坐。震為福。○紐，從宋元本，汲古等本皆訛紉。供，依宋元本，汲古作仙，非。</p><h3 id="否之困" tabindex="-1">否之困 <a class="header-anchor" href="#否之困" aria-label="Permalink to “否之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>白日揚光，雷車避藏。雲雨不行，各自還鄉。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽白離日，震雷震伏，故曰避藏。坎為雲雨，日出坎上，故雲雨不行。伏震為反，艮為鄉，故曰各自還鄉。○還，依汲古，宋元本作止。</p><h3 id="否之井" tabindex="-1">否之井 <a class="header-anchor" href="#否之井" aria-label="Permalink to “否之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>杜口結舌，心中怫鬱。去災生患，無所告冤。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>兌為口舌，坎伏，故杜口結舌。坎為心、為憂患凶災、為冤，上坎下互大坎，故無所告冤。○去，依汲古，宋元本作凶。</p><h3 id="否之革" tabindex="-1">否之革 <a class="header-anchor" href="#否之革" aria-label="Permalink to “否之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>賚貝贖狸，不聽我辭。繫於虎鬚，牽不得來。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《睽》。</p><h3 id="否之鼎" tabindex="-1">否之鼎 <a class="header-anchor" href="#否之鼎" aria-label="Permalink to “否之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>鳴鶴抱子，見蛇何咎。室傢俱在，不失其所。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為鶴、為子，艮手為抱。巽為蛇，兌見，故曰見蛇。鶴以蛇為糧，故無咎。艮為室家。○鳴，汲古作如，宋本作持，漢魏叢書本作鳴，下屢見亦多作鳴，故從之。</p><h3 id="否之震" tabindex="-1">否之震 <a class="header-anchor" href="#否之震" aria-label="Permalink to “否之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>逐兔山西，利走入門。賴我仁德，獲為我福。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為兔、為逐。艮山坎西，故曰山西。伏巽為利，艮為門。震為仁德、為福。○坎西證。</p><h3 id="否之艮" tabindex="-1">否之艮 <a class="header-anchor" href="#否之艮" aria-label="Permalink to “否之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>興役不休，與民爭時。牛生五趾，行危為憂。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互坎為勞，故曰興役不休。坎為眾、為民。艮為時，三上正反艮震，故曰爭時。震為生、為趾，坎納戊，數五，故曰五趾。艮為牛，坎為憂、為危。震行。按：《漢書五行志》：&quot;興徭役奪民時，厥妖牛生五足，秦孝文王五年，有獻五足牛者，劉向以為近牛禍&quot;，此自舊事，五行志述之，不得謂林本《漢書》。</p><h3 id="否之漸" tabindex="-1">否之漸 <a class="header-anchor" href="#否之漸" aria-label="Permalink to “否之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>春慄夏梨，山鮮希有。鬥千石萬，貴不可販。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為果，故曰慄梨。伏震為春，離為夏，艮為山，巽為魚，故曰山鮮。梨慄至春夏即壞，故曰希有。艮為鬥、為石、為貴、為求，伏震為千萬。○慄，依汲古，宋元作粟。山，依湖北局本，宋元、汲古皆作少，非。販，依宋元本，汲古作求。</p><h3 id="否之歸妹" tabindex="-1">否之歸妹 <a class="header-anchor" href="#否之歸妹" aria-label="Permalink to “否之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>悲號北行，失其長兄。伯仲不幸，骸骨散亡。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震聲兌口，坎悲坎北，故曰悲號北行。震為長兄，坎隱伏，兌折，故曰失其長兄。震為伯，坎為仲，兌為骸骨，兌折坎險，故曰不幸、曰散亡。</p><h3 id="否之豐" tabindex="-1">否之豐 <a class="header-anchor" href="#否之豐" aria-label="Permalink to “否之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>賦斂重數，政為民賊。杼軸空虛，去其家室。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>坎為聚，故曰賦斂，互大坎，故曰重數。坎為民、為賊、為杼軸，離虛故曰空。艮為家室，艮覆故去。○空虛去其家室，依《復》之《兌》校，各本皆作空盡家去其室。</p><h3 id="否之旅" tabindex="-1">否之旅 <a class="header-anchor" href="#否之旅" aria-label="Permalink to “否之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>履服白縞，殃咎併到，憂不能笑。通《節》。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>震為履、為服，巽為白、為縞，坎為殃咎、為憂，震為笑。○能，依汲古，宋元本作敢。</p><h3 id="否之巽" tabindex="-1">否之巽 <a class="header-anchor" href="#否之巽" aria-label="Permalink to “否之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>杜口結舌，言為禍母。代伯受患，無所禱免。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互兌為口舌、為言，正覆兌相背，故曰杜口結舌。巽為母，震為伯，震巽相往來，故曰代伯受患。兌為患，兌口為禱。○免，依汲古，宋元本作冤。</p><h3 id="否之兌" tabindex="-1">否之兌 <a class="header-anchor" href="#否之兌" aria-label="Permalink to “否之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>免冠進賢，步出朝門。儀體不正，賊孽為患。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。艮為冠，互震為進、為賢。進賢，冠名也。《漢書貢禹傳》：&quot;見責免冠謝&quot;，故曰免冠進賢。震為步、為出，艮為朝門，互坎為賊、為患。坎曲故不正。艮為身體。○步出朝門，儀體不正，依汲古，宋元作&quot;步行出朝，門體不正&quot;，非。</p><h3 id="否之渙" tabindex="-1">否之渙 <a class="header-anchor" href="#否之渙" aria-label="Permalink to “否之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>娶於薑女，駕迎新婦。少齊在門，夫子悅喜。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>巽為薑，震為娶、為駕，巽為婦、為少齊。《左傳昭二年》：&quot;晉人謂之少齊&quot;是也。艮為門，震為夫子、為悅喜。○少齊，依宋元本，汲古等本皆作少妻，非。夫子，亦依宋元本，汲古等本作之子，尤謬。</p><h3 id="否之節" tabindex="-1">否之節 <a class="header-anchor" href="#否之節" aria-label="Permalink to “否之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>牧羊稻園，聞虎喧歡。畏恐悚息，終無禍患。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《復》。</p><h3 id="否之中孚" tabindex="-1">否之中孚 <a class="header-anchor" href="#否之中孚" aria-label="Permalink to “否之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>老妾據機，緯絕不知。女功不成，冬寒無衣。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>兌為妾，老妾，本《大過九五》也。巽為進退、為機、為緯，兌折故緯絕、故女功不成。《左傳昭二十四年》：&quot;嫠不恤其緯而憂宗周之隕&quot;。乾為冬、為寒、為衣，今上下乾象皆缺，故無也。○據，依宋元本，汲古作踞。</p><h3 id="否之小過" tabindex="-1">否之小過 <a class="header-anchor" href="#否之小過" aria-label="Permalink to “否之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>黑龍吐光，使陰復明。燎獵載聖，六師以昌。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為龍，艮為黔，故曰黑龍。兌口為吐，艮為光明，故曰吐光、曰使陰復明。艮為火，故曰燎。震車為載，坎為聖，言文王出獵載太公以歸也。坎數六，坎眾，故曰六師。震為昌也。○明，依宋本，汲古作陽。燎，依宋元本，汲古作熊。惟黑依汲古，宋元本作乘。</p><h3 id="否之既濟" tabindex="-1">否之既濟 <a class="header-anchor" href="#否之既濟" aria-label="Permalink to “否之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>東鄰嫁女，為王妃後。莊公築館，以尊王母。歸於京師，季薑悅喜。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《觀》。○季薑，汲古作薑姬，依宋元本。《左傳桓九年》：&quot;紀季薑歸於京師，為桓公後&quot;是也，莊當為桓。</p><h3 id="否之未濟" tabindex="-1">否之未濟 <a class="header-anchor" href="#否之未濟" aria-label="Permalink to “否之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>灌頡東從，道頓跌踦。日辰不良，病為身禍。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，故曰灌頡。離為東，言顛頡從公子重耳於東也。灌疑為顛之音訛字。離為日，坎為病、為禍、為跌踦。○東從，依宋元本，汲古作同徒。日辰不良，依汲古，宋元本作日食不退，非。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
